package io.github.automacaofico.tracker;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import org.json.JSONObject;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class MainActivity extends AppCompatActivity{
 private static final int PERMISSIONS=41;private final Handler handler=new Handler(Looper.getMainLooper());private TextView equipmentTitle,title,detail,lastGps,lastSend,queueCount;private Button start,stop,activate,operatorButton;private LinearLayout activationPanel,trackingPanel,diagnosticPanel;private EditText registration,pin;private final Runnable refresh=new Runnable(){public void run(){render();handler.postDelayed(this,1000);}};
 @Override protected void onCreate(Bundle state){super.onCreate(state);if(prefs().getInt("credentialVersion",0)<2){prefs().edit().remove("deviceToken").remove("equipmentId").remove("operatorName").remove("operatorRegistration").putBoolean("running",false).apply();}setContentView(R.layout.activity_main);equipmentTitle=findViewById(R.id.equipmentTitle);title=findViewById(R.id.stateTitle);detail=findViewById(R.id.stateDetail);lastGps=findViewById(R.id.lastGps);lastSend=findViewById(R.id.lastSend);queueCount=findViewById(R.id.queueCount);start=findViewById(R.id.startButton);stop=findViewById(R.id.stopButton);activate=findViewById(R.id.activateButton);operatorButton=findViewById(R.id.operatorButton);activationPanel=findViewById(R.id.activationPanel);trackingPanel=findViewById(R.id.trackingPanel);diagnosticPanel=findViewById(R.id.diagnosticPanel);registration=findViewById(R.id.operatorRegistration);pin=findViewById(R.id.operatorPin);activate.setOnClickListener(v->enroll());operatorButton.setOnClickListener(v->openCheckin());start.setOnClickListener(v->requestAndStart());stop.setOnClickListener(v->{stopService(new Intent(this,TrackingService.class));prefs().edit().putBoolean("running",false).apply();render();});}
 @Override protected void onResume(){super.onResume();handler.post(refresh);}@Override protected void onPause(){super.onPause();handler.removeCallbacks(refresh);}private SharedPreferences prefs(){return getSharedPreferences("tracker",MODE_PRIVATE);}
 private void enroll(){String reg=registration.getText().toString().trim().toUpperCase(),secret=pin.getText().toString().trim();if(reg.length()<3){registration.setError("Informe a matrícula");return;}if(secret.length()<4){pin.setError("Informe o PIN");return;}activate.setEnabled(false);activate.setText("VINCULANDO…");new Thread(()->{try{String installation=prefs().getString("installationId",null);if(installation==null){installation=UUID.randomUUID().toString();prefs().edit().putString("installationId",installation).apply();}JSONObject request=new JSONObject().put("registration",reg).put("pin",secret).put("installationId",installation);HttpURLConnection c=(HttpURLConnection)new URL(BuildConfig.API_URL+"/api/v2/device/enroll").openConnection();c.setRequestMethod("POST");c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(request.toString().getBytes(StandardCharsets.UTF_8));}int status=c.getResponseCode();InputStream stream=status>=200&&status<300?c.getInputStream():c.getErrorStream();Scanner scanner=new Scanner(stream,StandardCharsets.UTF_8.name()).useDelimiter("\\A");String response=scanner.hasNext()?scanner.next():"{}";scanner.close();c.disconnect();JSONObject json=new JSONObject(response);if(status<200||status>=300)throw new IllegalStateException(json.optString("error","Não foi possível vincular."));prefs().edit().putString("deviceToken",json.getString("deviceToken")).putString("deviceId",json.getString("deviceId")).putString("operatorRegistration",json.getString("operatorRegistration")).putString("operatorName",json.getString("operatorName")).putInt("credentialVersion",2).remove("equipmentId").apply();runOnUiThread(()->{Toast.makeText(this,"Celular vinculado ao operador",Toast.LENGTH_LONG).show();pin.setText("");render();});}catch(Exception error){runOnUiThread(()->{Toast.makeText(this,error.getMessage(),Toast.LENGTH_LONG).show();activate.setEnabled(true);activate.setText("VINCULAR MEU CELULAR");});}}).start();}
 private void requestAndStart(){if(prefs().getString("deviceToken","").isEmpty()){detail.setText("Identifique o operador antes de iniciar.");return;}String[] permissions=Build.VERSION.SDK_INT>=33?new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.POST_NOTIFICATIONS}:new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION};if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,permissions,PERMISSIONS);else startTracking();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==PERMISSIONS&&ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)startTracking();else detail.setText("A localização precisa é necessária.");}
 private void startTracking(){ContextCompat.startForegroundService(this,new Intent(this,TrackingService.class));prefs().edit().putBoolean("running",true).apply();render();startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));openCheckin();}private void openCheckin(){String registration=prefs().getString("operatorRegistration","");startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://automacaofico.github.io/rastreamento/assumir/?matricula="+Uri.encode(registration))));}
 private void render(){SharedPreferences p=prefs();String name=p.getString("operatorName","");boolean enrolled=!p.getString("deviceToken","").isEmpty(),running=p.getBoolean("running",false);equipmentTitle.setText(enrolled?name:"FICO TRACKER");activationPanel.setVisibility(enrolled?View.GONE:View.VISIBLE);trackingPanel.setVisibility(enrolled?View.VISIBLE:View.GONE);diagnosticPanel.setVisibility(enrolled?View.VISIBLE:View.GONE);title.setText(running?"Transmitindo como "+name:"Rastreamento parado");detail.setText(running?"GPS ativo. O equipamento é definido pelo seu turno na Central FICO.":"Inicie e identifique o equipamento pelo QR Code.");start.setVisibility(running?View.GONE:View.VISIBLE);stop.setVisibility(running?View.VISIBLE:View.GONE);lastGps.setText("GPS: "+p.getString("lastGps","aguardando"));lastSend.setText("Servidor: "+p.getString("lastSend","nenhum envio"));queueCount.setText("Fila offline: "+p.getInt("queue",0)+" posições");}
}
